import curses
import sys
import json

def main(stdscr, data_str):
    curses.curs_set(0)
    stdscr.nodelay(False)
    lines = data_str.split('\n')
    max_y, max_x = stdscr.getmaxyx()

    offset = 0
    while True:
        stdscr.clear()
        for i in range(max_y - 1):
            if offset + i < len(lines):
                stdscr.addstr(i, 0, lines[offset + i][:max_x-1])

        # Draw status bar
        status = f" {(offset / max(1, len(lines))) * 100:.0f}%"
        stdscr.addstr(max_y - 1, 0, status[:max_x-1])
        stdscr.refresh()

        c = stdscr.getch()
        if c == ord('q'):
            break
        elif c == ord('j') or c == curses.KEY_DOWN:
            if offset < len(lines) - 1:
                offset += 1
        elif c == ord('k') or c == curses.KEY_UP:
            if offset > 0:
                offset -= 1

if __name__ == '__main__':
    data = json.dumps({'hello': 'world', 'a': 1}, indent=2)
    curses.wrapper(main, data)
