        path_str = path_str[1:]

    parts = re.findall(r'\["([^"]+)"\]|\[\'([^\']+)\'\]|\[(\d+)\]|([^\.\[\]]+)', path_str)
    for p in parts:
        p = p[0] or p[1] or p[2] or p[3]
        try:
            if p.isdigit() and isinstance(data, list):
                data = data[int(p)]
            else:
                data = data[p]
        except (KeyError, IndexError, TypeError):
            return None
    return data

