        return
    if '-v' in args or '--version' in args:
        print_version()
        return

    is_tty = sys.stdin.isatty()
    filename = ""

    if len(args) == 0:
        if is_tty:
            print_help()
            sys.exit(0)
        else:
            input_data = sys.stdin.read()
            process_args = []
    else:
        if is_tty:
            filename = args[0]
            try:
                with open(filename, 'r') as f:
                    input_data = f.read()
            except Exception as e:
                # fall back to using it as expression on empty object
                input_data = "{}"
                process_args = args
            else:
                process_args = args[1:]
        else:
